#!/usr/bin/env bash
set -Eeuo pipefail
role=preflight; server="${LINKSEND_SERVER:-}"; stun="${LINKSEND_STUN:-}"; bind="${LINKSEND_BIND:-}"; data_dir="${LINKSEND_DATA_DIR:-.stage2a/profile}"; receive_dir="${LINKSEND_RECEIVE_DIR:-}"; peer="${LINKSEND_PEER:-}"; skip=0; files=()
while (($#)); do case "$1" in --role) role="$2";shift 2;;--server) server="$2";shift 2;;--stun) stun="$2";shift 2;;--bind) bind="$2";shift 2;;--data-dir) data_dir="$2";shift 2;;--receive-dir) receive_dir="$2";shift 2;;--peer) peer="$2";shift 2;;--skip-build) skip=1;shift;;--) shift;files=("$@");break;;*) echo "未知参数: $1" >&2;exit 2;;esac;done
[[ -n "$server" ]]||{ echo '请提供 --server' >&2;exit 2; }; [[ "$server" != *127.0.0.1* && "$server" != *localhost* ]]||{ echo '2A 禁止 loopback 信令地址' >&2;exit 2; }; stamp=$(date +%Y%m%d-%H%M%S); evidence=".stage2a/$stamp"; mkdir -p "$evidence" "$data_dir"; command -v go >/dev/null||{ echo '未找到 Go 1.26.5' >&2;exit 1; }; go version|tee "$evidence/go-version.log"; host=$(python3 -c 'import sys,urllib.parse;print(urllib.parse.urlparse(sys.argv[1]).hostname)' "$server"); if command -v getent >/dev/null 2>&1; then getent hosts "$host"; elif command -v dscacheutil >/dev/null 2>&1; then dscacheutil -q host -a name "$host"; else host "$host"; fi | tee "$evidence/dns.log"; [[ $skip -eq 1 ]]||go build -trimpath -o "$evidence/linksend" ./cmd/linksend 2>&1|tee "$evidence/build.log"; printf '{"role":"%s","server":"%s","stun":"%s","bind":"%s","started":"%s","host":"%s"}\n' "$role" "$server" "$stun" "$bind" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$(hostname)" >"$evidence/run.json"; [[ "$role" == preflight ]]&&{ echo "2A 预检完成: $evidence";exit 0; }; [[ -n "$bind" ]]||{ echo '真实 2A 必须提供 --bind' >&2;exit 2; }; bin="$evidence/linksend"; [[ $skip -eq 1 ]]&&bin=go; common=(--server "$server" --data-dir "$data_dir"); if [[ "$role" == receiver ]];then [[ -n "$receive_dir" ]]||{ echo 'receiver 需要 --receive-dir' >&2;exit 2; }; "$bin" "${common[@]}" receive --dir "$receive_dir" --bind "$bind" --stun "$stun" --evidence --auto-accept 2>&1|tee "$evidence/transfer.log";else [[ -n "$peer" && ${#files[@]} -gt 0 ]]||{ echo 'sender 需要 --peer 和 -- 文件' >&2;exit 2; }; "$bin" "${common[@]}" send --peer "$peer" --bind "$bind" --stun "$stun" --evidence "${files[@]}" 2>&1|tee "$evidence/transfer.log";fi; echo "2A $role 完成: $evidence"
